def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, 18.0))

    winners_est = max(1, int(supply / WATER_REQ))

    prev_bids = []
    urgent_opp_bids = []
    weak_opp_count = 0
    rich_opp_count = 0
    for opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp_bids.append(float(bid))
        if opp.get('budget', 0) < DAILY_SALARY:
            weak_opp_count += 1
        if opp.get('budget', 0) > DAILY_SALARY * 2.2:
            rich_opp_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    urgent_prev = max(urgent_opp_bids) if urgent_opp_bids else highest_prev

    my_urgent = hp <= 3 or no_water >= 1
    critical = hp <= 2 or no_water >= 2

    if winners_est >= 2:
        if critical:
            bid = min(budget, max(92.0, urgent_prev + 2.0, highest_prev * 0.72))
        elif my_urgent:
            bid = min(budget, max(66.0, urgent_prev + 1.5, highest_prev * 0.52))
        else:
            if highest_prev >= 150:
                bid = min(budget, 24.0)
            elif highest_prev >= 110:
                bid = min(budget, 32.0)
            else:
                bid = min(budget, max(22.0, highest_prev * 0.28 + 3.0))
    else:
        if critical:
            bid = min(budget, max(118.0, urgent_prev + 3.0, highest_prev * 0.82))
        elif my_urgent:
            bid = min(budget, max(88.0, urgent_prev + 2.0, highest_prev * 0.68))
        else:
            bid = min(budget, max(54.0, highest_prev * 0.42 + 4.0))

    if weak_opp_count >= 2 and not my_urgent:
        bid = min(bid, 28.0 if winners_est >= 2 else 46.0)

    if rich_opp_count >= 2 and my_urgent:
        bid = min(budget, max(bid, highest_prev * 0.75 + 2.0))

    reserve_floor = DAILY_SALARY * max(0, 9 - int(day_context['day'])) * 0.18
    if budget - bid < reserve_floor and not critical:
        bid = max(0.0, budget - reserve_floor)

    bid = max(0.0, min(float(budget), float(bid)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents and their yesterday bids
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid', None)
            if bid is not None:
                alive_opps.append((opp_id, float(bid), opp))

    # Baseline bid depends on our HP and no-water streak
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # If we're in danger, bid high enough to secure water.
    if hp <= 2 or no_water_days >= 2:
        cap = min(budget, DAILY_SALARY * 0.95)
        return max(1.0, cap)

    # Use yesterday bids to infer pressure.
    if alive_opps:
        yesterday_bids = [b for _, b, _ in alive_opps]
        max_prev = max(yesterday_bids)
        avg_prev = sum(yesterday_bids) / float(len(yesterday_bids))

        # If others were bidding very high, we must avoid losing the water.
        if max_prev >= DAILY_SALARY * 0.85:
            # Medium bid: enough to beat high bidders but not burn budget.
            target = min(budget, DAILY_SALARY * 0.65)
        elif avg_prev >= DAILY_SALARY * 0.55:
            target = min(budget, DAILY_SALARY * 0.55)
        else:
            target = min(budget, DAILY_SALARY * 0.45)
    else:
        target = min(budget, DAILY_SALARY * 0.45)

    # Adjust for supply: higher supply reduces the need to overbid.
    # supply is between 15 and 25; scale smoothly.
    if supply >= 22.0:
        target *= 0.90
    elif supply <= 17.0:
        target *= 1.10

    # Ensure we don't bid more than budget; also keep bid positive.
    bid = float(target)
    if bid > budget:
        bid = budget
    if bid < 1.0:
        bid = 1.0

    return bid

